/* Narrative reports are generated by explicit local rules; no AI service is called. */
(function(){
'use strict';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ko=gz=>Array.from(gz).map(c=>Saju.KO[c]).join('');
window.mountInsights=function(r){
 // 재입력 시 이전에 삽입한 카드·상세 섹션을 제거해 중복을 막는다
 document.querySelectorAll('.saju-game, .detail-analysis').forEach(el=>el.remove());
 const deck=SajuCards.build(r),answers=Array(deck.length).fill(null);let index=0,finished=false;
 const section=document.createElement('section');section.className='saju-game';section.setAttribute('aria-label','사주 속 나 맞춰보기');
 document.querySelector('#result-content .result-grid').before(section);
 const choices=[['yes','😂','완전 나야'],['maybe','🤔','반쯤 맞아'],['no','🙅','난 아닌데']];
 function draw(focus=false){
  const answered=answers.filter(Boolean).length;
  if(finished){const yes=deck.filter((_,i)=>answers[i]==='yes');section.innerHTML=`<div class="game-intro"><span class="game-kicker">나와 사주 사이</span><h2>어디까지 닮았나요? 👀</h2><p>${deck.length}장 중 <strong>${yes.length}장</strong>에 ‘완전 나야’를 골랐어요.</p></div><div class="reaction-totals">${choices.map(([id,emoji,label])=>`<span>${emoji} ${label} <b>${answers.filter(a=>a===id).length}</b></span>`).join('')}</div><h3 class="game-result-heading">${yes.length?'내가 공감한 모습들 🫶':'딱 내 얘기인 카드는 없었네요 👀'}</h3>${yes.length?`<div class="kept-cards">${yes.map(c=>`<article><span>${c.emoji} ${safe(c.topic)}</span><h4>${safe(c.title)}</h4><p>${safe(c.text)}</p></article>`).join('')}</div>`:'<p class="game-empty">사주 속 모습과 실제 내가 다를 수도 있죠. 고른 답은 풀이를 바꾸지 않고, 이번 반응으로만 남겨요.</p>'}<details class="game-all"><summary>내가 고른 답 전체 보기</summary>${deck.map((c,i)=>`<div class="reaction-row"><span>${c.emoji} ${safe(c.title)}</span><b>${choices.find(x=>x[0]===answers[i])?.[2]||'아직 안 고름'}</b></div>`).join('')}</details><p class="game-note">이 숫자는 내가 고른 공감 반응이에요. 사주의 정확도를 측정한 점수는 아니에요.</p><div class="game-end-actions"><button type="button" class="button primary" data-action="restart">한 번 더 넘겨보기 ↺</button><button type="button" class="button secondary" data-action="edit">다른 사주 보기 ↗</button></div>`;
  }else{const c=deck[index];section.innerHTML=`<div class="game-intro"><span class="game-kicker">사주 속 나 vs 진짜 나</span><h2>이거… 나잖아? 👀</h2><p>사주에 담긴 모습 8장.<br>얼마나 닮았는지 가볍게 골라봐요.</p></div><div class="game-progress"><span>${String(index+1).padStart(2,'0')} <small>/ ${String(deck.length).padStart(2,'0')}</small></span><span>${answered}장 골랐어요</span></div><div class="game-track" role="progressbar" aria-label="고른 카드" aria-valuenow="${answered}" aria-valuemin="0" aria-valuemax="${deck.length}"><span style="width:${answered/deck.length*100}%"></span></div><article class="match-card tone-${index%4}" aria-labelledby="match-title"><div class="match-card-top"><span>${safe(c.topic)}</span><span>나의 사주 카드</span></div><div class="match-emoji" aria-hidden="true">${c.emoji}</div><h3 id="match-title" tabindex="-1">${safe(c.title)}</h3><p>${safe(c.text)}</p><span class="card-signature">사주 속 나는 이런 모습이래요 ✦</span></article><div class="reaction-buttons" role="group" aria-label="얼마나 나와 닮았나요?">${choices.map(([id,emoji,label])=>`<button type="button" data-answer="${id}" aria-pressed="${answers[index]===id}"><span aria-hidden="true">${emoji}</span><b>${label}</b></button>`).join('')}</div><div class="game-nav"><button type="button" data-action="prev" ${index===0?'disabled':''}>← 이전 카드</button><button type="button" class="game-next" data-action="next" ${answers[index]?'':'disabled'}>${index===deck.length-1?'내가 고른 카드 모아보기':'다음 카드'} →</button></div><p class="game-note">맞아도, 달라도 괜찮아요. 답을 골라도 카드 내용은 바뀌지 않아요.</p>`;}
  if(focus)(section.querySelector('#match-title')||section.querySelector('h2')).focus({preventScroll:true});
 }
 section.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.answer){answers[index]=b.dataset.answer;draw();section.querySelector(`[data-answer="${answers[index]}"]`).focus({preventScroll:true});return;}switch(b.dataset.action){case 'prev':index--;draw(true);break;case 'next':if(!answers[index])return;if(index===deck.length-1)finished=true;else index++;draw(true);break;case 'restart':index=0;finished=false;answers.fill(null);draw(true);break;case 'edit':document.querySelector('#another').click();break;}});
 draw();mountDetailAnalysis(r);
};

// ④ 상세 사주 분석: 계산되는 항목(형충회합)과 미계산 항목(신살 등)을 구분해 표시
function mountDetailAnalysis(r,data){
 const ZHI=Saju.ZHI;const kz=z=>Saju.KO[z]+'('+z+')';
 // 지지 관계: 원본 문서 6.4 정의 기준. 네 지지에서 실제로 성립하는 조합만 표시.
 const branches=r.pillars.map((p,i)=>p?{z:p.zhi,label:['시주','일주','월주','년주'][i]}:null).filter(Boolean);
 const SIXHARM=['子丑','寅亥','卯戌','辰酉','巳申','午未'];const found={harmony:[],clash:[]};
 for(let a=0;a<branches.length;a++)for(let b=a+1;b<branches.length;b++){const x=branches[a].z,y=branches[b].z;const pair=[x,y];if(SIXHARM.some(s=>s.includes(x)&&s.includes(y)&&x!==y))found.harmony.push(`${kz(x)}·${kz(y)} 육합`);if(Math.abs(ZHI.indexOf(x)-ZHI.indexOf(y))===6)found.clash.push(`${kz(x)}·${kz(y)} 육충`);}
 const detail=document.createElement('section');detail.className='detail-analysis';detail.setAttribute('aria-label','상세 사주 분석');
 const rel=found.harmony.length||found.clash.length?`${found.harmony.concat(found.clash).join(', ')}이(가) 확인돼요. 합은 잇고 조율하는 상징, 충은 다시 조정하는 상징으로 읽되 좋고 나쁨으로 단정하지 않아요.`:'확인된 지지 사이에서 이 해설이 확인하는 직접적인 육합·육충은 나타나지 않아요. 조용한 사주라는 뜻은 아닙니다.';
 detail.innerHTML=`<details class="detail-fold"><summary class="detail-summary"><span class="eyebrow">DETAILED CHART</span>상세 사주 분석 (전문 근거) <span class="detail-plus">+</span></summary>
 <div class="detail-body">
 <p class="detail-note">아래는 계산된 전문 정보예요. 위 해설과 같은 데이터에서 나왔습니다. 원국표와 오행 분포, 지장간·12운성 및 계산 기준을 여기서 확인할 수 있어요.</p>
 <div class="detail-card"><h4>형충회합 (지지 관계)</h4><p>${safe(rel)}</p></div>
 <div class="detail-card"><h4>추가 해석 기준이 필요한 항목</h4><p>신살(도화살·역마살 등), 용신 확정, 신강/신약, 월별 세운, 궁합은 이번 버전에서 <strong>계산하지 않았어요</strong>. ‘해당 없음’이 아니라 <strong>아직 계산하지 않은 항목</strong>이라는 뜻이에요. 구현과 검증이 끝난 결과만 표시하고 있어요.</p></div>
 <div class="detail-card"><h4>시주 경계에 대한 참고</h4><p>이 서비스는 자시를 23:00~01:00, 일주 변경을 자정(00:00)으로 계산해요. 원본 문서는 진태양시 기준 23:30~01:29를 자시로 보고 조자시(00:00~01:29)에 익일 일주를 적용하는 다른 방식이라, 자정 전후 출생은 결과가 달라질 수 있어요. 시간대만 고른 경우에는 분 단위 보정을 적용하지 않았습니다.</p></div>
 <div class="detail-chart-slot"></div>
 </div></details>`;
 document.querySelector('.result-end').before(detail);
 // 기존 원국표·오행 표(.result-grid)와 지장간/12운성/계산근거 패널을 상세 분석 안으로 옮겨, 기본 화면은 해설 중심이 되게 한다
 const slot=detail.querySelector('.detail-chart-slot');const grid=document.querySelector('#result-content .result-grid');if(grid)slot.appendChild(grid);
 document.querySelectorAll('#result-content > .details-panel').forEach(panel=>slot.appendChild(panel));
}
})();
